import XCTest
@testable import ClassingCore
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
final class CoreTests: XCTestCase {
    func state() throws -> AppState { var s = AppState(); s.settings["timezone"] = .string("Asia/Shanghai"); s.settings["semesterWeekStartDate"] = .string("2026-09-07"); var l = Lesson(title: "数学"); l.id = "math"; l.startMinute = 600; l.endMinute = 690; s.lessons = [l]; return s }
    func testIntegerJSONRoundTrip() throws { let v = JSONValue.int(9_007_199_254_740_993); XCTAssertEqual(try JSONValue.decode(v.data()), v) }
    func testLessonImportDefaultsAndValidation() throws { let l = try Lesson.fromImport(.object(["title": .string("数学"), "dayOfWeek": .int(2), "startTime": .string("08:00"), "endTime": .string("09:30")])); XCTAssertEqual(l.endWeek, 20); XCTAssertEqual(l.startMinute, 480); var invalid = l; invalid.endMinute = 1; XCTAssertThrowsError(try invalid.validate()) }
    func testWeekBoundaries() throws { XCTAssertEqual(try SchoolTime.weekIndex("2026-09-06", semester: "2026-09-07", weekStart: 1), 0); XCTAssertEqual(try SchoolTime.weekIndex("2026-09-14", semester: "2026-09-07", weekStart: 1), 2) }
    func testParityAndSemesterBounds() throws { var s = try state(); s.lessons[0].weekParity = "ODD"; XCTAssertEqual(try ScheduleProjector.project(s, from: "2026-09-07", through: "2026-09-14").count, 1); XCTAssertTrue(try ScheduleProjector.project(s, from: "2026-09-06", through: "2026-09-06").isEmpty) }
    func testWeeklyRuleCrossesSundayStart() throws { var r = ScheduleRule(anchorDate: "2026-09-07", endDate: "2026-12-31"); r.weekStartDay = 7; r.interval = 2; r.daysOfWeek = [1]; XCTAssertTrue(try r.matches("2026-09-07", fallbackDay: 1)); XCTAssertFalse(try r.matches("2026-09-14", fallbackDay: 1)); XCTAssertTrue(try r.matches("2026-09-21", fallbackDay: 1)) }
    func testRotationPausesOnHoliday() throws { var r = ScheduleRule(anchorDate: "2026-09-07", endDate: "2026-09-30"); r.kind = "ROTATION"; r.cycleLength = 3; r.cycleDays = [1]; r.holidays = ["2026-09-08"]; XCTAssertTrue(try r.matches("2026-09-11", fallbackDay: 1)); r.advanceOnHolidays = true; XCTAssertFalse(try r.matches("2026-09-11", fallbackDay: 1)); XCTAssertFalse(try r.matches("2026-09-12", fallbackDay: 1)) }
    func testDateRule() throws { var r = ScheduleRule(anchorDate: "2026-09-07", endDate: "2026-09-30"); r.kind = "DATES"; r.dates = ["2026-09-10"]; XCTAssertTrue(try r.matches("2026-09-10", fallbackDay: 1)); XCTAssertFalse(try r.matches("2026-09-07", fallbackDay: 1)) }
    func testCancelRescheduleAndMakeup() throws { var s = try state(); s.exceptions = [ScheduleException(type: "CANCEL", date: "2026-09-07", lessonId: "math")]; XCTAssertTrue(try ScheduleProjector.project(s, from: "2026-09-07", through: "2026-09-07").isEmpty); var e = ScheduleException(type: "RESCHEDULE", date: "2026-09-14", lessonId: "math"); e.startMinute = 720; e.endMinute = 810; e.location = "实验楼"; s.exceptions.append(e); let o = try ScheduleProjector.project(s, from: "2026-09-14", through: "2026-09-14"); XCTAssertEqual(o[0].startMinute, 720); XCTAssertEqual(o[0].source, "RESCHEDULED") }
    func testHolidayDoesNotCancelExplicitMakeup() throws { var s = try state(); var e = ScheduleException(type: "MAKE_UP", date: "2026-09-07"); e.title = "补课"; e.startMinute = 900; e.endMinute = 960; s.exceptions = [ScheduleException(type: "HOLIDAY", date: "2026-09-07"), e]; XCTAssertEqual(try ScheduleProjector.project(s, from: "2026-09-07", through: "2026-09-07").map(\.title), ["补课"]) }
    func testConflictDetection() throws { var s = try state(); var other = s.lessons[0]; other.id = "other"; other.startMinute = 660; other.endMinute = 720; s.lessons.append(other); XCTAssertEqual(ScheduleProjector.conflicts(try ScheduleProjector.project(s, from: "2026-09-07", through: "2026-09-07")).count, 1) }
    func testDSTGapRejectedAndOverlapFirst() throws { XCTAssertThrowsError(try SchoolTime.instant(date: "2026-03-08", minute: 150, zone: "America/New_York")); let overlap = try SchoolTime.instant(date: "2026-11-01", minute: 90, zone: "America/New_York"); XCTAssertEqual(overlap, ISO8601DateFormatter().date(from: "2026-11-01T05:30:00Z")) }
    func testInvalidDateRejected() { XCTAssertThrowsError(try SchoolTime.day("2026-02-30")); XCTAssertThrowsError(try SchoolTime.minute("25:00")) }
    func testRemindersDeduplicateAndCap() throws { var s = try state(); s.settings["reminderEnabled"] = .bool(true); let now = try SchoolTime.instant(date: "2026-09-07", minute: 540, zone: s.settings.timezone); let items = try ReminderPlanner.plan(s, now: now, limit: 3); XCTAssertEqual(items.count, 3); XCTAssertEqual(Set(items.map(\.id)).count, items.count); XCTAssertTrue(items.allSatisfy { $0.at > now }) }
    func testExamTimezoneAndCompletion() throws { var s = try state(); var e = Exam(title: "期末", start: Date(timeIntervalSince1970: 2_000_000_000), end: Date(timeIntervalSince1970: 2_000_003_600), timezone: "America/New_York"); e.completed = true; s.exams = [e]; XCTAssertFalse(try ReminderPlanner.plan(s).contains { $0.id.contains(e.id) }); e.endAt = e.startAt; XCTAssertThrowsError(try e.validate()) }
    func testLamportMergeCommutativeAndDeterministic() throws { var a = CloudDocument(), b = CloudDocument(); let stamp = LogicalVersion(counter: 3, deviceId: "a", changedAt: 5); a.records["mobile.settings"] = [VersionedRecord(id: "a", payload: "1", version: stamp)]; b.records["mobile.settings"] = [VersionedRecord(id: "a", payload: "2", version: stamp)]; XCTAssertEqual(try a.merged(with: b), try b.merged(with: a)); XCTAssertEqual(try a.merged(with: b).records["mobile.settings"]?[0].payload, "2") }
    func testDeleteWinsAndCompactsWithoutResurrecting() throws { var a = CloudDocument(), b = CloudDocument(); let stamp = LogicalVersion(counter: 1, deviceId: "a", changedAt: 1); a.records["timetable.lessons"] = [VersionedRecord(id: "x", payload: "alive", version: stamp)]; b.records["timetable.lessons"] = [VersionedRecord(id: "x", payload: "alive", version: stamp, deletedAt: 2, recoverableUntil: 3)]; let d = try a.merged(with: b, now: 4); XCTAssertNil(d.records["timetable.lessons"]?[0].payload); XCTAssertNotNil(d.records["timetable.lessons"]?[0].deletedAt) }
    func testWireUsesDomainAndDeviceArrays() throws { var s = try state(); try CloudSync.capture(&s, now: 100); let json = try JSONValue.encode(s.cloud); XCTAssertFalse(json["records"]["timetable.lessons"].array.isEmpty); XCTAssertEqual(json["devices"].array.count, 1) }
    func testCapturePropagatesDeletion() throws { var s = try state(); try CloudSync.capture(&s); s.lessons = []; try CloudSync.capture(&s); XCTAssertNotNil(s.cloud.records["timetable.lessons"]?.first?.deletedAt) }
    func testDisabledScopePreservesLocalAndIsNotUploaded() throws { var s = try state(); try CloudSync.capture(&s); let original = s.lessons; s.settings["syncScopes"] = .string("MOBILE_SETTINGS"); var remote = CloudDocument(); remote.records["timetable.lessons"] = []; try CloudSync.apply(remote, to: &s); XCTAssertEqual(s.lessons, original); XCTAssertNil(CloudSync.outbound(s).records["timetable.lessons"]) }
    func testMalformedCloudApplyIsAtomic() throws { var s = try state(); let original = s; var doc = CloudDocument(); doc.records["timetable.lessons"] = [VersionedRecord(id: "bad", payload: "{}", version: LogicalVersion(counter: 100, deviceId: "remote", changedAt: 0))]; XCTAssertThrowsError(try CloudSync.apply(doc, to: &s)); XCTAssertEqual(s, original) }
    func testAIProposalAtomicAndSnapshotChecked() throws { let s = try state(); let v = try JSONValue.decode(Data("{\"version\":1,\"actions\":[{\"operation\":\"update\",\"lessonId\":\"math\",\"lesson\":{\"title\":\"新名称\"}},{\"operation\":\"update\",\"lessonId\":\"missing\",\"lesson\":{\"title\":\"不存在\"}}]}".utf8)); XCTAssertThrowsError(try AIProposal.apply(v, exams: false, expected: s, current: s)); var changed = s; changed.lessons[0].title = "手工编辑"; XCTAssertThrowsError(try AIProposal.apply(v, exams: false, expected: s, current: changed)); XCTAssertEqual(s.lessons[0].title, "数学") }
    func testSSEMultilineCRAndComments() { var p = SSEParser(); XCTAssertNil(p.line(": heartbeat")); XCTAssertNil(p.line("event: delta")); XCTAssertNil(p.line("id: 7")); XCTAssertNil(p.line("data: first")); XCTAssertNil(p.line("data: second")); XCTAssertEqual(p.line(""), SSEEvent(event: "delta", data: "first\nsecond", id: "7")); XCTAssertNil(p.finish()) }
    func testICSExceptionsAndUnicodeRoundTrip() throws {
        let text = "BEGIN:VCALENDAR\r\nBEGIN:VEVENT\r\nUID:course\r\nDTSTART;TZID=Asia/Shanghai:20260907T100000\r\nDTEND;TZID=Asia/Shanghai:20260907T113000\r\nSUMMARY:数学\\,实验\r\nRRULE:FREQ=WEEKLY;COUNT=3;BYDAY=MO\r\nEXDATE;TZID=Asia/Shanghai:20260914T100000\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n"
        let draft = try ICS.parse(text, zone: "Asia/Shanghai"); XCTAssertEqual(draft.exceptions.count, 2); XCTAssertEqual(draft.exceptions[0].title, "数学,实验")
        var s = try state(); s.lessons = []; s.exceptions = draft.exceptions; let output = try ICS.export(s, from: "2026-09-07", through: "2026-10-01"); XCTAssertEqual(try ICS.parse(output, zone: "Asia/Shanghai").exceptions.count, 2)
    }
    func testICSRejectsUnsupportedRuleInsteadOfGuessing() { let text = "BEGIN:VCALENDAR\nBEGIN:VEVENT\nDTSTART:20260907T100000Z\nDTEND:20260907T110000Z\nRRULE:FREQ=WEEKLY;BYSETPOS=1\nEND:VEVENT\nEND:VCALENDAR"; XCTAssertThrowsError(try ICS.parse(text, zone: "UTC")) }
    func testICSRecurrenceCancellation() throws { let text = "BEGIN:VCALENDAR\nBEGIN:VEVENT\nUID:x\nDTSTART:20260907T100000Z\nDTEND:20260907T110000Z\nSUMMARY:数学\nRRULE:FREQ=WEEKLY;COUNT=2\nEND:VEVENT\nBEGIN:VEVENT\nUID:x\nRECURRENCE-ID:20260914T100000Z\nSTATUS:CANCELLED\nEND:VEVENT\nEND:VCALENDAR"; XCTAssertEqual(try ICS.parse(text, zone: "UTC").exceptions.count, 1) }
    func testSharedDemoFixtureImports() throws {
        var url = URL(fileURLWithPath: #filePath); for _ in 0..<4 { url.deleteLastPathComponent() }; url.appendPathComponent("Fixtures/demo.json")
        let draft = try ScheduleImport.json(Data(contentsOf: url)); XCTAssertGreaterThan(draft.lessons.count, 3); XCTAssertEqual(draft.exams.count, 1)
    }
    func testWebDAVRequiresHTTPS() { XCTAssertThrowsError(try WebDAVCloud(url: URL(string: "http://example.invalid/file")!, username: "", password: "")) }
    func testBYOKRequiresHTTPSAndDoesNotAcceptHeaderInjection() { XCTAssertThrowsError(try BYOKClient(endpoint: URL(string: "http://example.invalid/v1")!, model: "x", key: "key")); XCTAssertThrowsError(try BYOKClient(endpoint: URL(string: "https://example.invalid/v1")!, model: "x", key: "bad\nkey")) }
    func testAccountAndAndroidSignatureHeadersAreNotSent() async throws { let transport = CaptureTransport(), vault = MemoryTokenVault(); let api = ClassingAPI(baseURL: URL(string: "https://example.invalid")!, vault: vault, platform: "IOS", bundleID: "com.example.apple", transport: transport); _ = try await api.request("GET", "/api/v1/auth/registration/config", authorized: false); let request = await transport.last; XCTAssertEqual(request?.value(forHTTPHeaderField: "X-Classing-Client-Platform"), "IOS"); XCTAssertNil(request?.value(forHTTPHeaderField: "X-Classing-Signing-Cert-Sha256")); XCTAssertNil(request?.value(forHTTPHeaderField: "X-Classing-Package-Name")) }
}
private actor CaptureTransport: HTTPTransport {
    var last: URLRequest?
    func send(_ request: URLRequest, limit: Int) -> HTTPResponse { last = request; return HTTPResponse(status: 200, data: Data("{}".utf8)) }
    func stream(_ request: URLRequest, onEvent: @escaping @Sendable (SSEEvent) async throws -> Void) async throws {}
}
